import json
S='/tmp/claude-0/-var-tmp-bench-ws-Rr3Xf0vv/3da37679-5c50-4bca-b58c-1b787ede92d7/scratchpad/clasif.txt'
ids=[json.loads(l)['id'] for l in open('incidencias.jsonl')]
AREAS={'windows-os','sandbox','app-server','connectivity','TUI','session','rate-limits','tool-calls','browser','remote','model-behavior','performance','mcp','auth','context','subagent','config','computer-use'}
TIPOS={'bug','enhancement','documentation'}
SUP={'app','CLI','extension','codex-web','iOS'}
out={}
errs=[]
for line in open(S,encoding='utf-8'):
    line=line.rstrip('\n')
    if not line: continue
    f=line.split('|')
    i,t,s,a=f[0],f[1],f[2],f[3]
    nota='|'.join(x for x in f[4:] if x)
    areas=[x for x in a.split(',') if x]
