    if t not in TIPOS: errs.append(('tipo',i,t))
    if s not in SUP: errs.append(('sup',i,s))
    for x in areas:
        if x not in AREAS: errs.append(('area',i,x))
    d={'id':i,'tipo':t,'superficie':s,'areas':areas}
    if nota: d['nota']=nota
    out[i]=d
missing=[i for i in ids if i not in out]
extra=[i for i in out if i not in ids]
print('lineas',len(out),'faltan',missing,'sobran',extra,'errores',errs)
with open('clasificacion.jsonl','w',encoding='utf-8') as fh:
    for i in ids:
        fh.write(json.dumps(out[i],ensure_ascii=False)+'\n')
"
wc -l clasificacion.jsonl && head -3 clasificacion.jsonl && python3 -c "
